/**
 * @name funpay.EleanorMay-theme
 * @author EleanorMay
 * @version 1.0.0
 * @description Dark FunPay theme with a muted C.C. green accent.
 * @source https://funpay.com/
 */

/*
 * The two local images are intentionally kept as relative URLs:
 * assets/wallpaper.gif - global page wallpaper
 * assets/sphere.png - profile header sphere
 */

/* ==UserStyle==
@name           funpay.EleanorMay-theme
@namespace      funpay-rpc
@version        1.0.0
@description    Dark FunPay theme with a muted green accent.
==/UserStyle== */

@-moz-document url-prefix("https://funpay.com/") {

:root {
    --fp-lime: #d6e88a;
    --fp-lime-hover: #e7f3b0;
    --fp-lime-soft: rgba(214, 232, 138, 0.16);
    --fp-black: #000;
    --fp-surface: #0b0b0b;
    --fp-raised: #151515;
    --fp-raised-2: #1d1d1d;
    --fp-text: #e9f0d2;
    --fp-muted: #aeb69b;
    --fp-faint: #77806b;
    --fp-border: rgba(214, 232, 138, 0.30);
    --fp-border-strong: rgba(214, 232, 138, 0.52);
    --fp-shadow: 0 12px 32px rgba(0, 0, 0, 0.42);
    --fp-wallpaper: url("data:image/gif;base64,");
    --fp-profile-sphere: url("data:image/png;base64,");
}

html,
body {
    min-height: 100%;
    background-color: #000 !important;
    background-image: none !important;
    color: var(--fp-text) !important;
}

body {
    position: relative !important;
    isolation: isolate;
    font-family: "Segoe UI", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
    font-size: 14px;
    line-height: 1.45;
}

body::before {
    content: "";
    position: fixed;
    z-index: 0;
    inset: 0;
    pointer-events: none;
    background-image: linear-gradient(180deg, rgba(0, 0, 0, 0.40), rgba(0, 0, 0, 0.72)), var(--fp-wallpaper);
    background-position: center top;
    background-size: cover;
    background-repeat: no-repeat;
    filter: blur(10px) saturate(115%);
    transform: scale(1.04);
}

body > * {
    position: relative;
    z-index: 1;
}

/* Base layout */

.wrapper,
.wrapper-content,
#content,
#content-body {
    background: transparent !important;
}

#header {
    position: relative;
    z-index: 10000 !important;
    background: rgba(0, 0, 0, 0.91) !important;
    border-bottom: 1px solid var(--fp-border) !important;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.30);
}

#header > .container,
#header .navbar,
#header .container-fluid {
    background: transparent !important;
}

.navbar,
.navbar-default,
.navbar-default .navbar-collapse,
.navbar-default .navbar-form {
    border-color: transparent !important;
}

.navbar-default .navbar-brand,
.navbar-default .navbar-nav > li > a,
.navbar-default .navbar-nav > .open > a,
.navbar-default .navbar-nav > .active > a {
    color: var(--fp-text) !important;
    background: transparent !important;
}

.navbar-default .navbar-brand:hover,
.navbar-default .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > li > a:focus,
.navbar-default .navbar-nav > .open > a:hover {
    color: var(--fp-lime) !important;
    background: var(--fp-lime-soft) !important;
}

.navbar-brand .logo-color {
    filter: brightness(0) saturate(100%) invert(88%) sepia(24%) saturate(622%) hue-rotate(31deg) brightness(104%);
}

.navbar-default .navbar-toggle {
    border-color: var(--fp-border) !important;
    background: var(--fp-raised) !important;
}

.navbar-default .navbar-toggle:hover,
.navbar-default .navbar-toggle:focus {
    background: var(--fp-lime-soft) !important;
}

.navbar-default .navbar-toggle .icon-bar {
    background-color: var(--fp-lime) !important;
}

/* Links, text and icons */

a,
a:visited,
.text-main,
.game-title a,
.media-user-name,
.tc-user a,
.tc-header a,
.social-statistic-info {
    color: var(--fp-lime) !important;
}

a:hover,
a:focus,
.game-title a:hover,
.media-user-name:hover,
.tc-user a:hover,
.tc-header a:hover {
    color: var(--fp-lime-hover) !important;
}

.text-muted,
.tc-desc,
.tc-desc-text,
.media-user-reviews,
.counter-param,
.footer-block,
.footer-block a {
    color: var(--fp-muted) !important;
}

.fas,
.fab,
svg,
svg * {
    color: currentColor;
}

/* Search and form controls */

.form-control,
input,
textarea,
select,
.form-control-box {
    color: var(--fp-text) !important;
    background: rgba(21, 21, 21, 0.94) !important;
    background-image: none !important;
    border: 1px solid var(--fp-border) !important;
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.40) !important;
}

.form-control::placeholder,
input::placeholder,
textarea::placeholder {
    color: var(--fp-faint) !important;
    opacity: 1;
}

.form-control:focus,
input:focus,
textarea:focus,
select:focus {
    color: var(--fp-text) !important;
    border-color: var(--fp-lime) !important;
    outline: none !important;
    box-shadow: 0 0 0 1px var(--fp-lime), 0 0 14px rgba(214, 232, 138, 0.14) !important;
}

.promo-games-filter .form-control {
    background: rgba(11, 11, 11, 0.92) !important;
}

.checkbox,
.switch,
.checkbox-switch {
    accent-color: var(--fp-lime) !important;
}

/* Buttons */

.btn,
button {
    border-radius: 5px !important;
    transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.btn-primary,
.btn-primary:active,
.btn-primary.active,
.btn-primary:focus,
.btn-primary:hover,
.btn-success,
.btn-success:active,
.btn-success:focus,
.btn-success:hover,
.btn-warning,
.btn-warning:active,
.btn-warning:focus,
.btn-warning:hover,
.btn-round.btn-primary {
    color: #050600 !important;
    background: var(--fp-lime) !important;
    border-color: var(--fp-lime) !important;
    box-shadow: 0 4px 14px rgba(214, 232, 138, 0.12);
}

.btn-primary:hover,
.btn-success:hover,
.btn-warning:hover,
.btn-round.btn-primary:hover {
    background: var(--fp-lime-hover) !important;
    border-color: var(--fp-lime-hover) !important;
    color: #050600 !important;
}

.btn-default,
.btn-gray,
.btn-link,
.btn-default:focus,
.btn-gray:focus {
    color: var(--fp-text) !important;
    background: var(--fp-raised) !important;
    border-color: var(--fp-border) !important;
}

.btn-default:hover,
.btn-gray:hover,
.btn-link:hover {
    color: var(--fp-lime) !important;
    background: var(--fp-lime-soft) !important;
    border-color: var(--fp-border-strong) !important;
}

.btn.disabled,
.btn[disabled],
fieldset[disabled] .btn {
    color: var(--fp-faint) !important;
    background: #101010 !important;
    border-color: rgba(255, 255, 255, 0.10) !important;
    opacity: 0.75;
}

/* Dropdowns and popovers */

.dropdown-menu,
.dropdown-autocomplete,
.navbar-default .navbar-nav .open .dropdown-menu {
    color: var(--fp-text) !important;
    background: rgba(11, 11, 11, 0.98) !important;
    border: 1px solid var(--fp-border) !important;
    border-radius: 6px !important;
    box-shadow: var(--fp-shadow) !important;
}

.dropdown-menu > li > a,
.dropdown-menu .menu-item,
.dropdown-menu label {
    color: var(--fp-text) !important;
}

.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus,
.dropdown-menu .active > a,
.dropdown-menu label:hover {
    color: var(--fp-lime) !important;
    background: var(--fp-lime-soft) !important;
}

/* Panels and marketplace surfaces */

.panel,
.panel-default,
.panel-body,
.panel-heading,
.block-info,
.showcase,
.showcase-filters,
.showcase-table,
.offer,
.tc,
.content-with-cd-wide {
    color: var(--fp-text) !important;
    background: rgba(11, 11, 11, 0.88) !important;
    border-color: var(--fp-border) !important;
    box-shadow: var(--fp-shadow) !important;
}

.panel-heading,
.tc-header,
.offer-tc-container,
.counter-list,
.showcase-filter-text {
    background: rgba(21, 21, 21, 0.92) !important;
    border-color: var(--fp-border) !important;
}

.panel-title,
.tc-header,
.tc-price,
.offer .tc-header,
.lead,
h1,
h2,
h3,
h4,
h5 {
    color: var(--fp-text) !important;
}

.panel-title a,
.tc-price,
.counter-value,
.unit {
    color: var(--fp-lime) !important;
}

.offer,
.tc {
    border-radius: 7px !important;
}

.offer:hover,
.tc:hover,
.table-clickable:hover {
    border-color: var(--fp-border-strong) !important;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(214, 232, 138, 0.08) !important;
}

.table,
.table > tbody > tr > td,
.table > thead > tr > th,
.table-hover > tbody > tr:hover {
    color: var(--fp-text) !important;
    background: transparent !important;
    border-color: rgba(214, 232, 138, 0.18) !important;
}

.table-hover > tbody > tr:hover,
.tc-item:hover {
    background: var(--fp-lime-soft) !important;
}

.tc-short,
.tc-desc,
.tc-desc-text {
    color: var(--fp-muted) !important;
}

.tc-price {
    font-weight: 700;
    text-shadow: 0 0 12px rgba(214, 232, 138, 0.18);
}

.avatar-photo {
    border: 1px solid var(--fp-border) !important;
    box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.45);
}

.online::after {
    background-color: var(--fp-lime) !important;
    box-shadow: 0 0 8px var(--fp-lime);
}

/* FunPay home page */

.content-promo,
.promo-games,
.promo-games-all,
.promo-game-list,
.promo-game-list-header {
    background: transparent !important;
}

.promo-cd {
    background: rgba(0, 0, 0, 0.40) !important;
    border-color: var(--fp-border) !important;
    border-radius: 10px !important;
    box-shadow: var(--fp-shadow) !important;
}

.promo-cd .cd-container,
.promo-cd .cd,
.promo-cd .social-statistic-list,
.promo-cd .cd-satellite {
    filter: saturate(0.78) brightness(0.82);
}

.promo-cd .cd-satellite,
.social-statistic {
    color: var(--fp-text) !important;
    background: rgba(11, 11, 11, 0.72) !important;
    border-color: var(--fp-border) !important;
}

.promo-cd .cd-satellite:hover,
.social-statistic:hover {
    color: var(--fp-lime) !important;
    background: var(--fp-lime-soft) !important;
}

.promo-game-list-header,
.nav-abc {
    background: rgba(11, 11, 11, 0.82) !important;
    border: 1px solid var(--fp-border) !important;
    border-radius: 7px !important;
}

.nav-abc a,
.promo-game-list-title,
.title-mini {
    color: var(--fp-lime) !important;
}

.promo-game-item {
    min-height: 100%;
    padding: 13px 15px !important;
    background: rgba(11, 11, 11, 0.74) !important;
    border: 1px solid rgba(214, 232, 138, 0.19) !important;
    border-radius: 7px !important;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.24);
}

.promo-game-item:hover {
    background: rgba(21, 21, 21, 0.92) !important;
    border-color: var(--fp-border-strong) !important;
    transform: translateY(-1px);
}

.game-title a {
    color: var(--fp-text) !important;
}

.promo-game-item ul a {
    color: var(--fp-muted) !important;
}

.promo-game-item ul a:hover {
    color: var(--fp-lime) !important;
}

/* Profile pages: use sphere.png as the profile header */

.profile,
.profile-header,
.profile-cover,
.profile-cover-container {
    background: transparent !important;
}

.profile-cover {
    position: relative !important;
    overflow: hidden !important;
    isolation: isolate;
    border-bottom: 1px solid var(--fp-border) !important;
    background: transparent !important;
}

.profile-cover-container {
    position: absolute !important;
    overflow: hidden !important;
    z-index: 0 !important;
    pointer-events: none !important;
}

/* The compact profile popover must not inherit the large circular cover. */
.popover .profile-cover-container,
.popover .profile-cover-img {
    display: none !important;
}

.profile-cover-img {
    background-image: var(--fp-profile-sphere) !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: 100% 100% !important;
    z-index: 0 !important;
    filter: blur(10px) saturate(0.78) brightness(0.72);
    transform: scale(1.04);
}

/* Keep the real page header and its account menu above the profile artwork. */

#header .navbar-right.logged .dropdown-menu,
#header .navbar-nav .dropdown-menu,
#header .dropdown-menu {
    z-index: 10001 !important;
    background: rgba(11, 11, 11, 0.98) !important;
    border-color: var(--fp-border) !important;
    box-shadow: var(--fp-shadow) !important;
}

/* A cover is decorative; it must never paint over text or controls. */

.profile-cover > .avatar,
.profile-cover > .profile,
.profile-cover > h1,
.profile-cover > .media-user,
.profile-cover > *:not(.profile-cover-container) {
    position: relative !important;
    z-index: 2 !important;
}

.profile-cover-container,
.profile-cover-img {
    pointer-events: none !important;
}

.profile h1,
.profile .h1,
.profile .media-user-name,
.profile .media-user-info {
    color: var(--fp-text) !important;
    text-shadow: 0 2px 12px #000;
}

.profile .panel,
.profile .block-info {
    background: rgba(11, 11, 11, 0.91) !important;
}

/* Keep the profile page and review area on the wallpaper instead of white. */
#content > .container,
#content-body > .container,
.wrapper-content > .container,
.profile .container,
.profile .row,
.profile-content .container,
.profile-page .container,
.profile > .container,
.profile > .container-fluid,
.profile-content,
.profile-page,
.profile-page-content,
.profile-content-wrapper {
    background: transparent !important;
    background-image: none !important;
}

/* FunPay wraps the lower profile section in .bg-light-color (#f9f9f9). */

#content-body,
#content,
.bg-light-color,
.bg-light-color > .container,
.bg-light-color .container,
.bg-light-color .profile-container,
.bg-light-color .profile-data-container,
.bg-light-color .dyn-table,
.bg-light-color .dyn-table-body,
.bg-light-color .review-container,
.bg-light-color .review-item,
.bg-light-color .review-item-row {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
}

.bg-light-color .offer,
.bg-light-color .tc,
.bg-light-color .panel,
.bg-light-color .review-item-answer {
    background: rgba(11, 11, 11, 0.88) !important;
}

.bg-light-color .review-container {
    border-top-color: var(--fp-border) !important;
}

.main-container,
.profile-container,
.profile-data-container,
.page-content,
.page-content-full,
.review-container,
.review-item,
.review-item-answer {
    color: var(--fp-text) !important;
    background: transparent !important;
    background-image: none !important;
}

body,
html {
    background-color: #000 !important;
}

.profile [class*="review"],
.profile [class*="feedback"] {
    color: var(--fp-text) !important;
    background-color: rgba(11, 11, 11, 0.91) !important;
    border-color: var(--fp-border) !important;
}

.profile [class*="review"] a,
.profile [class*="feedback"] a {
    color: var(--fp-lime) !important;
}

/* Keep profile popups and their controls above decorative cover artwork. */
.modal,
.modal-dialog,
.popover,
.dropdown-menu,
[role="dialog"] {
    z-index: 2000 !important;
}

/* Chat, alerts and authentication dialogs */

.chat-header,
.chat-message,
.chat-form,
.chat-promo,
.alert,
.modal-content,
.modal-header,
.modal-body,
.modal-footer,
.banner-cookie-consent,
.modal-cookie-consent {
    color: var(--fp-text) !important;
    background: rgba(11, 11, 11, 0.95) !important;
    border-color: var(--fp-border) !important;
}

.chat-message:hover,
.chat-promo:hover {
    background: rgba(21, 21, 21, 0.96) !important;
}

.alert a,
.modal-title,
.modal-header .close,
.cc-text {
    color: var(--fp-text) !important;
}

.modal-backdrop {
    background: #000 !important;
    opacity: 0.78 !important;
}

.close:hover,
.modal-header .close:hover {
    color: var(--fp-lime) !important;
}

/* Make the whole FunPay logo area one clickable link. */

#header a.navbar-brand,
#header .navbar-brand {
    position: relative !important;
    z-index: 10002 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    box-sizing: border-box !important;
    width: 120px !important;
    min-width: 120px !important;
    height: 64px !important;
    padding: 0 12px !important;
    margin: 0 !important;
    cursor: pointer !important;
}

#header .navbar-brand img,
#header .navbar-brand .logo-color {
    display: block !important;
    max-width: 100% !important;
    max-height: 100% !important;
    pointer-events: none !important;
}

/* The base site paints the chat shell white. Keep it dark/translucent too. */

.chat,
.chat-full,
.chat-box,
.chat-contacts,
.chat-detail,
.chat-panel,
.chat-panel-mobile,
.chat-full-header,
.chat-message-container,
.chat-message-list,
.chat-empty,
.chat-form,
.chat-form-input .form-control,
.chat-form-input .hiddendiv,
.chat-not-selected,
.chat-not-selected .chat-message-container {
    color: var(--fp-text) !important;
    background: rgba(11, 11, 11, 0.88) !important;
    background-color: rgba(11, 11, 11, 0.88) !important;
    border-color: var(--fp-border) !important;
}

.chat-message-list-date,
.chat-message-list-date .inside {
    background: rgba(21, 21, 21, 0.94) !important;
    color: var(--fp-muted) !important;
}

/* Half-sphere artwork from 171080.json, recolored by the current palette. */

:root {
    --fp-legacy-sphere: url("data:image/jpeg;base64,");
}

.profile-cover-img {
    background-image: var(--fp-legacy-sphere) !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: 55% auto !important;
    background-color: transparent !important;
}

.cd svg,
.promo-cd .cd svg {
    background-image: var(--fp-legacy-sphere) !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: 100% 100% !important;
}

/* Footer */

.wrapper-footer,
#footer {
    color: var(--fp-muted) !important;
    background: rgba(0, 0, 0, 0.90) !important;
    border-top: 1px solid var(--fp-border) !important;
}

.footer-block-social .btn {
    color: var(--fp-lime) !important;
}

.footer-block-als img {
    filter: brightness(0) invert(1) opacity(0.62);
}

/* Cookie consent */

.banner-cookie-consent,
.modal-cookie-consent {
    box-shadow: var(--fp-shadow) !important;
}

.cc-accept-all,
.cc-save {
    color: #050600 !important;
    background: var(--fp-lime) !important;
    border-color: var(--fp-lime) !important;
}

.cc-options {
    color: var(--fp-text) !important;
    background: var(--fp-raised) !important;
    border-color: var(--fp-border) !important;
}

/* Scrollbars */

* {
    scrollbar-color: var(--fp-lime) #080808;
    scrollbar-width: thin;
}

::-webkit-scrollbar {
    width: 9px;
    height: 9px;
    background: #080808 !important;
}

::-webkit-scrollbar-thumb {
    background: var(--fp-lime) !important;
    border: 2px solid #080808;
    border-radius: 9px;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--fp-lime-hover) !important;
}

@media (max-width: 767px) {
    html,
    body {
        background-position: 62% top !important;
        background-attachment: scroll !important;
    }

    #header,
    .wrapper-footer {
        background: rgba(0, 0, 0, 0.96) !important;
    }

    .navbar-default .navbar-nav .open .dropdown-menu > li > a {
        color: var(--fp-text) !important;
    }

    .promo-game-item {
        padding: 10px !important;
    }

    .profile-cover-img {
        background-size: auto 100% !important;
    }
}

/* Final palette overrides for the main page and chat selection. */
.nav-abc,
.nav-abc .nav,
.nav-abc ul {
    background: transparent !important;
    background-color: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
}

.content-lots-node .cd-forward,
.content-lots-node .cd-forward .counter-list,
.content-lots-node .content-with-cd-wide.showcase {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
}

/* Do not show the sphere artwork in user profile headers. */
.profile-cover-img {
    background: transparent !important;
    background-image: none !important;
    background-color: transparent !important;
}

/* Remove the solid slabs behind the category pills and alphabet. */
.content-promo .counter-list,
.content-promo .counter-list.counter-list-circles,
.counter-list.counter-list-circles,
.promo-games .counter-list,
.promo-games-all .counter-list,
.promo-game-list-header,
.promo-game-list-header .nav-abc,
.promo-game-list-header .nav-abc .nav,
.promo-game-list-header .nav-abc ul {
    background: transparent !important;
    background-color: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
}

.counter-list.counter-list-circles > .counter-item,
.counter-list > .counter-item {
    color: var(--fp-text) !important;
    background: rgba(11, 14, 10, 0.92) !important;
    background-color: rgba(11, 14, 10, 0.92) !important;
    border-color: rgba(117, 141, 61, 0.58) !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.28) !important;
}

